            <span class="message-timestamp">12:31 PM</span>
          </div>
        </div>
        <div class="chat-message user-message">
          <div class="message-content">
            <p class="message-text">Can you recommend some good restaurants in the area?</p>
            <span class="message-timestamp">12:32 PM</span>
          </div>
        </div>
        <div class="chat-message bot-message">
          <div class="message-content">
            <p class="message-text">Absolutely! Here are some highly-rated restaurants near you: [insert recommendations]</p>
            <span class="message-timestamp">12:33 PM</span>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Add the JavaScript to handle the modal -->
  <script>
    // Get the modal
    const modal = document.getElementById("modal");

    // Get the button that opens the modal
    const showModalButton = document.getElementById("show-modal");

    // Get the <span> element that closes the modal
    const closeModalButton = document.querySelector(".close-modal");

    // When the user clicks the button, open the modal
    showModalButton.addEventListener("click", () => {
      modal.style.display = "block";
    });

    // When the user clicks on <span> (x), close the modal
